    static constexpr int Left=168,Top=46,Row=76;QScrollBar*verticalScroll=nullptr;int dragLayer=-1,dragEffect=-1,dragKey=-1,dragMode=0,scrollOffset=0;int selectedLayerKeyLayer=-1,selectedLayerKey=-1,selectedBendKeyLayer=-1,selectedBendKey=-1;double pressTime=0,originalStart=0,originalEnd=0,originalLayerStart=0,originalLayerEnd=0,horizontalOffset=0;QPointF pressPosition;QVector<EffectPoint>originalKeys;QVector<Keyframe>originalLayerKeys;QVector<BendKeyframe>originalBendKeys;QVector<EffectClip>originalLayerEffects;struct KeyHit{int layer=-1,effect=-1,key=-1;bool valid=false;};struct LayerKeyHit{int layer=-1,key=-1;bool bend=false,valid=false;};struct EffectHit{int layer=-1,effect=-1;bool valid=false;};
    double timelineScale()const{return(width()-Left-12.0)/std::max(.1,duration)*zoom;}double maxHorizontalOffset()const{return std::max(0.0,(width()-Left-12.0)*(zoom-1.0));}double xForTime(double value)const{return Left+value*timelineScale()-horizontalOffset;}int visualRowForLayer(int layer)const{return layers?layers->size()-1-layer:-1;}int layerForVisualRow(int row)const{return layers&&row>=0&&row<layers->size()?layers->size()-1-row:-1;}int layerAtY(double y)const{return y<Top?-1:layerForVisualRow(int((y-Top+scrollOffset)/Row));}int effectLaneAtY(double y)const{int layer=layerAtY(y);if(layer<0)return-1;int local=int(y-Top+scrollOffset)%Row;return local>=0&&local<=31?layer:-1;}
