    KeyHit keyAt(const QPointF&pos)const{if(!layers||pos.x()<Left)return{};for(int layer=0;layer<layers->size();layer++)for(int effect=0;effect<layers->at(layer).effects.size();effect++){const auto&clip=layers->at(layer).effects[effect];double y=effectRect(layer,clip).center().y();for(int key=0;key<clip.keys.size();key++)if(QLineF(pos,{xForTime(clip.keys[key].time),y}).length()<9)return{layer,effect,key,true};}return{};}
    LayerKeyHit layerKeyAt(const QPointF&pos)const{if(!layers||pos.x()<Left)return{};const int layer=layerAtY(pos.y());if(layer<0)return{};const QRectF clip=layerRect(layer);for(int key=0;key<layers->at(layer).keys.size();key++)if(QLineF(pos,{xForTime(layers->at(layer).keys[key].time),clip.center().y()+6}).length()<9)return{layer,key,false,true};for(int key=0;key<layers->at(layer).bendKeys.size();key++)if(QLineF(pos,{xForTime(layers->at(layer).bendKeys[key].time),clip.center().y()-6}).length()<9)return{layer,key,true,true};return{};}
