    void drawWaveformEnvelope(QPainter&p,const QRectF&clip)const{if(!waveform||waveform->isEmpty())return;const int left=std::max(Left,int(std::floor(clip.left()))),right=std::min(width()-verticalScroll->width(),int(std::ceil(clip.right())));if(right<=left)return;const double center=clip.center().y(),half=clip.height()*.42;QVarLengthArray<QLineF,2048>lines;lines.reserve(right-left+1);for(int x=left;x<=right;x++){const double t=std::clamp(timeFromX(x,false)/std::max(.001,duration),0.0,1.0);const int index=std::clamp(qRound(t*(waveform->size()-1)),0,int(waveform->size()-1));const double amplitude=waveform->at(index)*half;lines.append(QLineF(x,center-amplitude,x,center+amplitude));}const bool previousAntialiasing=p.testRenderHint(QPainter::Antialiasing);p.setRenderHint(QPainter::Antialiasing,false);p.setPen(QPen(QColor(130,255,229),1));p.drawLines(lines.constData(),lines.size());p.setRenderHint(QPainter::Antialiasing,previousAntialiasing);}
    double timeFromX(double x,bool snap)const{double t=std::clamp((x-Left+horizontalOffset)/std::max(1.0,timelineScale()),0.0,duration);if(snappingEnabled&&snap&&beats&&!beats->isEmpty()){auto it=std::min_element(beats->begin(),beats->end(),[t](double a,double b){return std::abs(a-t)<std::abs(b-t);});if(it!=beats->end()&&std::abs(*it-t)<10.0/std::max(1.0,timelineScale()))t=*it;}return t;}
