    void addEffectClip(EffectKind kind,int layerIndex=-1,double requestedStart=-1){
        if(layerIndex<0)layerIndex=layerList->currentRow();
        if(layerIndex<0||layerIndex>=layers.size()){QMessageBox::information(this,"Efectos","Selecciona una capa y suelta el efecto en la pista morada superior.");return;}
        pushUndoState();Layer&layer=layers[layerIndex];double maxEnd=std::min(duration,layer.endTime);double wanted=requestedStart>=0?requestedStart:current;
        double start=std::clamp(wanted,layer.startTime,std::max(layer.startTime,maxEnd-.05)),end=std::min(maxEnd,start+1.2);
        if(end<=start+.049){start=layer.startTime;end=std::min(maxEnd,start+1.2);}
        EffectClip clip;clip.id=QUuid::createUuid().toString(QUuid::WithoutBraces);clip.kind=int(kind);clip.name=effectName(kind);clip.start=start;clip.end=end;
        double neutralAmount=kind==EffectKind::Fade?100.0:0.0;
        clip.keys={{start,neutralAmount,Ease::Linear,50,100,100},{end,neutralAmount,Ease::Linear,50,100,100}};
        layer.effects.push_back(clip);layerList->setCurrentRow(layerIndex);selectEffectClip(layerIndex,layer.effects.size()-1);setTime(start,true);timeline->update();canvas->update();
    }
