    void syncAudioTimeline(){if(!timeline)return;timeline->audioLoaded=!audioPath.isEmpty();timeline->audioName=audioPath;timeline->update();}
    void requestWaveformAnalysis(){
        const QString requestedPath=audioPath;const int generation=++waveformGeneration;waveform.clear();syncAudioTimeline();
        if(requestedPath.isEmpty()||!QFileInfo::exists(requestedPath))return;
        QPointer<MainWindow>guard(this);QThreadPool::globalInstance()->start([guard,requestedPath,generation]{
            QString error;QVector<float>peaks=analyzeWaveform(requestedPath,error);if(!guard)return;
            QMetaObject::invokeMethod(guard.data(),[guard,requestedPath,generation,peaks=std::move(peaks),error]()mutable{
                if(!guard||guard->waveformGeneration!=generation||guard->audioPath!=requestedPath)return;
                if(error.isEmpty())guard->waveform=std::move(peaks);guard->syncAudioTimeline();
                guard->statusBar()->showMessage(error.isEmpty()?"Forma de onda lista":"No se pudo crear la forma de onda: "+error,3000);
            },Qt::QueuedConnection);
        });
    }
    static QString clockText(double seconds){int minutes=int(seconds)/60;double rest=seconds-minutes*60;return QString("%1:%2").arg(minutes,2,10,QChar('0')).arg(rest,6,'f',3,QChar('0'));}
    void setTime(double t,bool syncAudio){current=std::clamp(t,0.0,duration);canvas->time=current;timeline->setPlayhead(current);timeLabel->setText(clockText(current)+" / "+clockText(duration));if(timelineTimeLabel){const int totalFrames=qRound(current*std::max(1,fps));const int frames=totalFrames%std::max(1,fps);const int totalSeconds=totalFrames/std::max(1,fps);timelineTimeLabel->setText(QString("%1:%2:%3:%4").arg(totalSeconds/3600,2,10,QChar('0')).arg((totalSeconds/60)%60,2,10,QChar('0')).arg(totalSeconds%60,2,10,QChar('0')).arg(frames,2,10,QChar('0')));}const bool playing=(!audioPath.isEmpty()&&player->playbackState()==QMediaPlayer::PlayingState)||silentTimer->isActive();canvas->realtimePlayback=playing;if(!playing){loadProps();loadEffectProps();}canvas->update();if(syncAudio&&!audioPath.isEmpty())player->setPosition(qint64(current*1000));}
    void togglePlay(){if(!audioPath.isEmpty()){if(player->playbackState()==QMediaPlayer::PlayingState)player->pause();else{player->setPosition(qint64(current*1000));player->play();}}else{if(silentTimer->isActive()){silentTimer->stop();canvas->realtimePlayback=false;loadProps();loadEffectProps();}else{silentStart=current>=duration?0:current;elapsed.restart();canvas->realtimePlayback=true;silentTimer->start();}}canvas->update();}
    void importAudio(){QString p=QFileDialog::getOpenFileName(this,"Importar audio",{},"Audio/Vídeo (*.wav *.mp3 *.m4a *.aac *.ogg *.flac *.mp4 *.mov *.mkv)");if(p.isEmpty())return;audioPath=p;player->setSource(QUrl::fromLocalFile(p));player->pause();requestWaveformAnalysis();statusBar()->showMessage("Audio importado · generando forma de onda…",3000);}
    void extractAudio(){QString in=QFileDialog::getOpenFileName(this,"Vídeo de origen",{},"Vídeo (*.mp4 *.mov *.mkv *.webm *.avi)");if(in.isEmpty())return;QString out=QFileDialog::getSaveFileName(this,"Guardar audio",QFileInfo(in).completeBaseName()+".wav","WAV (*.wav);;MP3 (*.mp3)");if(out.isEmpty())return;QStringList a={"-y","-hide_banner","-loglevel","error","-i",in,"-vn"};if(out.endsWith(".mp3",Qt::CaseInsensitive))a<<"-c:a"<<"libmp3lame"<<"-q:a"<<"2";else a<<"-c:a"<<"pcm_s16le";a<<out;QString e;if(!runProcess(toolPath("ffmpeg.exe"),a,&e,300000))QMessageBox::critical(this,"FFmpeg",e);else{audioPath=out;player->setSource(QUrl::fromLocalFile(out));requestWaveformAnalysis();statusBar()->showMessage("Audio extraído e importado · generando forma de onda…",3000);}}
    void autoBeats(){if(audioPath.isEmpty()){QMessageBox::information(this,"Auto beats","Importa audio primero.");return;}QProgressDialog d("Analizando flujo espectral...",{},0,0,this);d.setWindowModality(Qt::WindowModal);d.show();QApplication::processEvents();QString e;auto a=analyzeAudio(audioPath,e);if(!e.isEmpty()){QMessageBox::critical(this,"Auto beats",e);return;}beats=a.beats;waveform=a.waveform;timeline->update();statusBar()->showMessage(QString("%1 beats detectados · BPM estimado %2").arg(beats.size()).arg(a.bpm,0,'f',1),6000);}
